21	/**
22	 * Indicates a fatal boot problem, among {@link ErrorObject}
23	 *
24	 * @author Kohsuke Kawaguchi
25	 * @see WebAppMain#recordBootAttempt(File)
26	 */
27	public abstract class BootFailure extends ErrorObject {
28	    protected BootFailure() {
29	    }
30	
31	    protected BootFailure(Throwable cause) {
32	        super(cause);
33	    }
34	
35	    /**
36	     * Exposes this failure to UI and invoke the hook.
37	     *
38	     * @param home
39	     *      JENKINS_HOME if it's already known.
40	     */
41	    public void publish(ServletContext context, @CheckForNull File home) {
42	        LOGGER.log(Level.SEVERE, "Failed to initialize Jenkins", this);
43	
44	        WebApp.get(context).setApp(this);
45	        if (home == null) {
46	            return;
47	        }
48	        new GroovyHookScript("boot-failure", context, home, BootFailure.class.getClassLoader())
49	                .bind("exception", this)
50	                .bind("home", home)
51	                .bind("servletContext", context)
52	                .bind("attempts", loadAttempts(home))
53	                .run();
54	    }
55	
56	    /**
57	     * Parses the boot attempt file carefully so as not to cause the entire hook script to fail to execute.
58	     */
59	    protected List<Date> loadAttempts(File home) {
60	        List<Date> dates = new ArrayList<>();
61	        if (home != null) {
62	            File f = getBootFailureFile(home);
63	            try {
64	                if (f.exists()) {
65	                    try (BufferedReader failureFileReader = Files.newBufferedReader(f.toPath(), Charset.defaultCharset())) {
66	                        String line;
67	                        // WebAppMain.recordBootAttempt uses Date.toString when writing, so that is the format we must parse.
68	                        SimpleDateFormat df = new SimpleDateFormat("EEE MMM dd HH:mm:ss zzz yyyy");
69	                        while ((line = failureFileReader.readLine()) != null) {
70	                            try {
71	                                dates.add(df.parse(line));
72	                            } catch (Exception e) {
73	                                // ignore any parse error
74	                            }
75	                        }
76	                    }
77	                }
78	            } catch (IOException | InvalidPathException e) {
79	                LOGGER.log(Level.WARNING, "Failed to parse " + f, e);
80	            }
81	        }
82	        return dates;
83	    }
84	
85	    private static final Logger LOGGER = Logger.getLogger(BootFailure.class.getName());
86	
87	    /**
88	     * This file captures failed boot attempts.
89	     * Every time we try to boot, we add the timestamp to this file,
90	     * then when we boot, the file gets deleted.
91	     */
92	    public static File getBootFailureFile(File home) {
93	        return new File(home, "failed-boot-attempts.txt");
94	    }
95	
96	}

