51	/**
52	 * Provides the capability for starting/stopping/restarting/uninstalling Hudson.
53	 *
54	 * <p>
55	 * The steps to perform these operations depend on how Hudson is launched,
56	 * so the concrete instance of this method (which is VM-wide singleton) is discovered
57	 * by looking up a FQCN from the system property "hudson.lifecycle".
58	 * (This may be set to a class defined in a plugin,
59	 * in which case the singleton switches during startup.)
60	 * @author Kohsuke Kawaguchi
61	 * @since 1.254
62	 */
63	public abstract class Lifecycle implements ExtensionPoint {
64	    private static Lifecycle INSTANCE = null;
65	
66	    /**
67	     * Gets the singleton instance.
68	     */
69	    @NonNull
70	    public static synchronized Lifecycle get() {
71	        if (INSTANCE == null) {
72	            Lifecycle instance;
73	            String p = SystemProperties.getString("hudson.lifecycle");
74	            if (p != null) {
75	                try {
76	                    ClassLoader cl = Jenkins.get().getPluginManager().uberClassLoader;
77	                    instance = (Lifecycle) cl.loadClass(p).getDeclaredConstructor().newInstance();
78	                } catch (NoSuchMethodException e) {
79	                    NoSuchMethodError x = new NoSuchMethodError(e.getMessage());
80	                    x.initCause(e);
81	                    throw x;
82	                } catch (InstantiationException e) {
83	                    InstantiationError x = new InstantiationError(e.getMessage());
84	                    x.initCause(e);
85	                    throw x;
86	                } catch (IllegalAccessException e) {
87	                    IllegalAccessError x = new IllegalAccessError(e.getMessage());
88	                    x.initCause(e);
89	                    throw x;
90	                } catch (ClassNotFoundException e) {
91	                    LOGGER.log(Level.FINE, e, () -> "Failed to load " + p + " so will try again later");
92	                    instance = new PlaceholderLifecycle();
93	                } catch (InvocationTargetException e) {
94	                    Throwable t = e.getCause();
95	                    if (t instanceof RuntimeException) {
96	                        throw (RuntimeException) t;
97	                    } else if (t instanceof IOException) {
98	                        throw new UncheckedIOException((IOException) t);
99	                    } else if (t instanceof Exception) {
100	                        throw new RuntimeException(t);
101	                    } else if (t instanceof Error) {
102	                        throw (Error) t;
103	                    } else {
104	                        throw new Error(e);
105	                    }
106	                }
107	            } else {
108	                if (Functions.isWindows()) {
109	                    instance = new Lifecycle() {
110	                        @Override
111	                        public void verifyRestartable() throws RestartNotSupportedException {
112	                            throw new RestartNotSupportedException(
113	                                    "Default Windows lifecycle does not support restart.");
114	                        }
115	                    };
116	                } else if (System.getenv("SMF_FMRI") != null && System.getenv("SMF_RESTARTER") != null) {
117	                    // when we are run by Solaris SMF, these environment variables are set.
118	                    instance = new SolarisSMFLifecycle();
119	                } else if (System.getenv("NOTIFY_SOCKET") != null) {
120	                    // When we are running under systemd with Type=notify, this environment variable is set.
121	                    instance = new SystemdLifecycle();
122	                } else {
123	                    // if run on Unix, we can do restart
124	                    try {
125	                        instance = new UnixLifecycle();
126	                    } catch (final Throwable t) {
127	                        LOGGER.log(Level.WARNING, "Failed to install embedded lifecycle implementation", t);
128	                        instance = new Lifecycle() {
129	                            @Override
130	                            public void verifyRestartable() throws RestartNotSupportedException {
131	                                throw new RestartNotSupportedException(
132	                                        "Failed to install embedded lifecycle implementation, so cannot restart: " + t, t);
133	                            }
134	                        };
135	                    }
136	                }
137	            }
138	            assert instance != null;
139	            INSTANCE = instance;
140	        }
141	
142	        return INSTANCE;
143	    }
144	
145	    /**
146	     * If the location of {@code jenkins.war} is known in this life cycle,
147	     * return it location. Otherwise return null to indicate that it is unknown.
148	     *
149	     * <p>
150	     * When a non-null value is returned, Hudson will offer an upgrade UI
151	     * to a newer version.
152	     */
153	    public File getHudsonWar() {
154	        String war = SystemProperties.getString("executable-war");
155	        if (war != null && new File(war).exists())
156	            return new File(war);
157	        return null;
158	    }
159	
160	    /**
161	     * Replaces jenkins.war by the given file.
162	     *
163	     * <p>
164	     * On some system, most notably Windows, a file being in use cannot be changed,
165	     * so rewriting {@code jenkins.war} requires some special trick. Override this method
166	     * to do so.
167	     */
168	    public void rewriteHudsonWar(File by) throws IOException {
169	        File dest = getHudsonWar();
170	        // this should be impossible given the canRewriteHudsonWar method,
171	        // but let's be defensive
172	        if (dest == null)  throw new IOException("jenkins.war location is not known.");
173	
174	        // backing up the old jenkins.war before it gets lost due to upgrading
175	        // (newly downloaded jenkins.war and 'backup' (jenkins.war.tmp) are the same files
176	        // unless we are trying to rewrite jenkins.war by a backup itself
177	        File bak = new File(dest.getPath() + ".bak");
178	        if (!by.equals(bak))
179	            FileUtils.copyFile(dest, bak);
180	
181	        FileUtils.copyFile(by, dest);
182	        // we don't want to keep backup if we are downgrading
183	        if (by.equals(bak)) {
184	            Files.deleteIfExists(Util.fileToPath(bak));
185	        }
186	    }
187	
188	    /**
189	     * Can {@link #rewriteHudsonWar(File)} work?
190	     */
191	    public boolean canRewriteHudsonWar() {
192	        // if we don't know where jenkins.war is, it's impossible to replace.
193	        File f = getHudsonWar();
194	        if (f == null || !f.canWrite()) {
195	            return false;
196	        }
197	        File parent = f.getParentFile();
198	        if (parent == null || !parent.canWrite()) {
199	            return false;
200	        }
201	        return true;
202	    }
203	
204	    /**
205	     * If this life cycle supports a restart of Hudson, do so.
206	     * Otherwise, throw {@link UnsupportedOperationException},
207	     * which is what the default implementation does.
208	     *
209	     * <p>
210	     * The restart operation may happen synchronously (in which case
211	     * this method will never return), or asynchronously (in which
212	     * case this method will successfully return.)
213	     *
214	     * <p>
215	     * Throw an exception if the operation fails unexpectedly.
216	     */
217	    public void restart() throws IOException, InterruptedException {
218	        throw new UnsupportedOperationException();
219	    }
220	
221	    /**
222	     * Can the {@link #restart()} method restart Hudson?
223	     *
224	     * @throws RestartNotSupportedException
225	     *      If the restart is not supported, throw this exception and explain the cause.
226	     */
227	    public void verifyRestartable() throws RestartNotSupportedException {
228	        // the rewriteHudsonWar method isn't overridden.
229	        if (!Util.isOverridden(Lifecycle.class, getClass(), "restart"))
230	            throw new RestartNotSupportedException("Restart is not supported in this running mode (" +
231	                    getClass().getName() + ").");
232	    }
233	
234	    /**
235	     * The same as {@link #verifyRestartable()} except the status is indicated by the return value,
236	     * not by an exception.
237	     */
238	    public boolean canRestart() {
239	        try {
240	            verifyRestartable();
241	            return true;
242	        } catch (RestartNotSupportedException e) {
243	            return false;
244	        }
245	    }
