277	     * Called when Jenkins is beginning its shutdown.
278	     *
279	     * @since 2.333
280	     */
281	    public void onStop(@NonNull String user, @CheckForNull String remoteAddr) {
282	        if (remoteAddr != null) {
283	            LOGGER.log(
284	                    Level.INFO,
285	                    "Stopping Jenkins as requested by {0} from {1}",
286	                    new Object[] {user, remoteAddr});
287	        } else {
288	            LOGGER.log(Level.INFO, "Stopping Jenkins as requested by {0}", user);
289	        }
290	    }
