327	    @Restricted(NoExternalUse.class)
328	    public static final class PlaceholderLifecycle extends ExitLifecycle {
329	
330	        @Initializer(after = InitMilestone.PLUGINS_STARTED, before = InitMilestone.EXTENSIONS_AUGMENTED)
331	        public static synchronized void replacePlaceholder() {
332	            if (get() instanceof PlaceholderLifecycle) {
333	                String p = SystemProperties.getString("hudson.lifecycle");
334	                try {
335	                    INSTANCE = (Lifecycle) Jenkins.get().getPluginManager().uberClassLoader.loadClass(p).getConstructor().newInstance();
336	                    LOGGER.fine(() -> "Updated to " + INSTANCE);
337	                } catch (Exception | LinkageError x) {
338	                    LOGGER.log(Level.WARNING, x, () -> "Failed to load " + p + "; using fallback exit lifecycle");
339	                }
340	            }
341	        }
342	
343	    }
