36	/**
37	 * {@link Lifecycle} that delegates the responsibility to restart Jenkins to an external
38	 * watchdog such as SystemD or OpenRC.
39	 *
40	 * <p>
41	 * Restart by exit with specific code.
42	 *
43	 * @author Alon Bar-Lev
44	 */
45	@Restricted(NoExternalUse.class)
46	@Extension
47	public class ExitLifecycle extends Lifecycle {
48	
49	    private static final Logger LOGGER = Logger.getLogger(ExitLifecycle.class.getName());
50	
51	    private static final String EXIT_CODE_ON_RESTART = "exitCodeOnRestart";
52	    private static final String DEFAULT_EXIT_CODE = "5";
53	
54	    private Integer exitOnRestart;
55	
56	    public ExitLifecycle() {
57	        exitOnRestart = Integer.parseInt(SystemProperties.getString(Jenkins.class.getName() + "." + EXIT_CODE_ON_RESTART, DEFAULT_EXIT_CODE));
58	    }
59	
60	    @Override
61	    @SuppressFBWarnings(value = "DM_EXIT", justification = "Exit is really intended.")
62	    public void restart() {
63	        Jenkins jenkins = Jenkins.getInstanceOrNull(); // guard against repeated concurrent calls to restart
64	
65	        try {
66	            if (jenkins != null) {
67	                jenkins.cleanUp();
68	            }
69	        } catch (Throwable e) {
70	            LOGGER.log(Level.SEVERE, "Failed to clean up. Restart will continue.", e);
71	        }
72	
73	        System.exit(exitOnRestart);
74	    }
75	}
